import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@repo/design-system/components/ui/card";
import { cn } from "@repo/design-system/lib/utils";
import type { LucideIcon } from "lucide-react";
import type { ComponentProps, ReactNode } from "react";

type MetricCardProps = {
  label: string;
  value: string | number;
  detail?: ReactNode;
  trend?: ReactNode;
  icon?: LucideIcon;
  className?: string;
} & ComponentProps<typeof Card>;

export function MetricCard({
  label,
  value,
  detail,
  trend,
  icon: Icon,
  className,
  ...props
}: MetricCardProps) {
  return (
    <Card
      className={cn(
        "border-border/80 bg-card/95 shadow-black/5 shadow-sm",
        className
      )}
      {...props}
    >
      <CardHeader className="flex flex-row items-start justify-between gap-4 space-y-0 pb-3">
        <div className="space-y-1">
          <CardDescription className="font-semibold text-[11px] uppercase tracking-[0.12em]">
            {label}
          </CardDescription>
          <CardTitle className="font-semibold text-2xl tracking-tight">
            {value}
          </CardTitle>
        </div>
        {Icon ? (
          <span className="flex size-9 items-center justify-center rounded-xl border border-primary/10 bg-primary/10 text-primary">
            <Icon className="size-4" />
          </span>
        ) : null}
      </CardHeader>
      {(detail || trend) && (
        <CardContent className="flex items-center justify-between gap-3 pt-0">
          <span className="text-muted-foreground text-sm">{detail}</span>
          {trend ? (
            <span className="font-semibold text-primary text-xs">{trend}</span>
          ) : null}
        </CardContent>
      )}
    </Card>
  );
}
